const body = $json.body ?? $json;
let action = String(body.action ?? '').trim();
const preferredDate = String(body.preferred_date ?? body.date ?? '').trim();
const preferredTime = String(body.preferred_time ?? '').trim();
const enquiryId = String(body.enquiry_id ?? '').trim();

if (!action) action = preferredTime ? 'request_booking' : 'availability_for_date';

return [{ json: { action, preferred_date: preferredDate, preferred_time: preferredTime, enquiry_id: enquiryId } }];

const d = $json ?? {};

if (d.ok === true && d.booking_status === 'requested') {
  return [{ json: d }];
}

if (d.ok === true && d.is_open === true) {
  const slots = Array.isArray(d.slots) ? d.slots.slice(0, 8).map((s) => String(s).slice(0, 5)) : [];
  return [{ json: { ...d, reply: slots.length ? `Demo availability for ${d.date}: ${slots.join(', ')}. Appointment requests still require Favfare staff confirmation.` : `There are no remaining demo slots for ${d.date}.` } }];
}

if (d.ok === true && d.is_open === false) {
  return [{ json: { ...d, reply: `Favfare is closed for the demo schedule on ${d.date}. Please choose another date.` } }];
}

return [{ json: { ...d, reply: d.reply ?? 'I could not complete that booking request. A Favfare team member can assist.' } }];
